import ctypes
import os

from datetime import datetime
from typing import List

from .data_layer.message_handling import (Manager,
                                          u32,
                                          change_endianness)
from .data_layer.msg_general_report import BrowserGeneralReportInd
from .data_layer.msg_misc import MiscInterface

from .file_operations import build_trace_file_header, build_trace_file_name, build_in_memory_file, ZipSaver, TxtSaver

from .data_layer.sack_reflection_interface import get_browser_object_name

from .commons import LOGGER


class BaseCollector(object):
    def __init__(self):
        self.board = None
        self.cpu = None

        self.start_qm = None  # type: Manager
        self.stop_qm = None  # type: Manager
        self.ind_m = None  # type: Manager

        self.start_time = None  # type: datetime
        self.stop_time = None  # type: datetime

    def prepare_query_managers(self, *args, **kwargs):
        raise NotImplementedError

    def start(self):
        self.start_time = datetime.now()
        if not self:
            LOGGER.debug('Start request not sent')
            return
        LOGGER.debug('Sending start request for 0x{:x}{:x}'.format(self.board, self.cpu))
        self.start_qm.send_request_and_wait_for_response()

    def stop(self):
        self.stop_time = datetime.now()
        if not self:
            LOGGER.debug('Stop request not sent')
            return
        LOGGER.debug('Sending stop request for 0x{:x}{:x}'.format(self.board, self.cpu))
        self.stop_qm.send_request_and_wait_for_response()

    def __bool__(self):
        return bool(self.board)

    __nonzero__ = __bool__


class BaseTraceCollector(BaseCollector):

    def __init__(self, connection):
        super(BaseTraceCollector, self).__init__()
        self.connection = connection

        self.report_name = None  # type: int
        self.meas_period = None

        self.trace_name = ''

        self.output_path = os.path.join('/', 'home', 'ute')

    @property
    def all_inds(self):
        try:
            return self.ind_m.all_inds
        except AttributeError:
            return []

    def set_parameters(self, **kwargs):
        for key, value in kwargs.items():
            setattr(self, key, value)

        if not self.trace_name:
            self.trace_name = get_browser_object_name(self.report_name)

    def save_traces(self, output_path, as_zip=True):
        if not self.all_inds:
            LOGGER.warning('No {} collected'.format(self.trace_name))
            return

        sw_version = MiscInterface(self.connection).get_browser_sw_version(self.board, self.cpu)
        all_traces = prepare_report_data_for_export_to_txt_file(self.ind_m.all_inds)
        board, cpu = self.board, self.cpu
        file_name = build_trace_file_name(board, cpu, self.trace_name, self.stop_time)
        file_path = os.path.join(output_path, file_name)
        file_header = build_trace_file_header(
            len(all_traces), self.report_name, sw_version, self.start_time, self.stop_time
        )

        in_memory_txt_file = build_in_memory_file(file_header, all_traces)

        saver = ZipSaver if as_zip else TxtSaver
        return saver(in_memory_txt_file, file_path).save()

    def prepare_query_managers(self, *args, **kwargs):
        raise NotImplementedError


class BaseMeasurementCollector(BaseCollector):
    def __init__(self, connection):
        super(BaseMeasurementCollector, self).__init__()
        self.connection = connection

    def prepare_query_managers(self, *args, **kwargs):
        raise NotImplementedError

    def set_parameters(self, **kwargs):
        for key, value in kwargs.items():
            setattr(self, key, value)


def prepare_report_data_for_export_to_txt_file(collected_ind_byte_streams):
    # type: (List[bytearray]) -> List[str]
    """
    An Ind (BrowserGeneralReportInd), as any message, consists of a header and a payload.
    The dynamic part of payload consists of itemNumber*itemSize u32 numbers.

    In the output file, each line is built as:

    header_fields,static_part_of_payload_fields,itemSize_of_u32_numbers_from_dynamic_part_of_payload

    and such a line is repeated itemCount times per EVERY ind.

    Based on function `WriteTtiTrace` in DSP Explorer source code.
    """
    processed_data = []

    offset = ctypes.sizeof(BrowserGeneralReportInd) - ctypes.sizeof(u32)

    for ind_byte_stream in collected_ind_byte_streams:
        report = BrowserGeneralReportInd().deserialize(ind_byte_stream)

        header_part = _get_header_part(report)
        payload_static_part = _get_payload_static_part(report)

        data_array = u32 * (report.itemCount * report.itemSize)
        # this will have to be removed once response messages are handled as VariableSizeMessages
        if not report.payload_is_little_endian:
            payload_dynamic_part = data_array.from_buffer_copy(change_endianness(ind_byte_stream[offset:]))
        else:
            payload_dynamic_part = data_array.from_buffer_copy(ind_byte_stream[offset:])
        #

        for item in range(report.itemCount):
            entry = header_part + ',' + payload_static_part

            from_ = item * report.itemSize
            to_ = (item + 1) * report.itemSize
            data = ','.join(['{:d}'.format(f) for f in payload_dynamic_part[from_:to_]])

            if data:
                entry += ',' + data
            entry += ';\r\n'

            processed_data.append(entry)

    return processed_data


def prepare_rake_traces_for_export_to_txt_file(collected_ind_byte_streams):
    # type: (List[bytearray]) -> List[str]
    """
    based on script.lua -> WriteRakeTrace
    """

    data_shift_n = 8
    data_marker = 0xEEEEEE
    data_mask = 0xFF
    line_term = ';\r\n'

    processed_data = []

    offset = ctypes.sizeof(BrowserGeneralReportInd) - ctypes.sizeof(u32)

    for ind_byte_stream in collected_ind_byte_streams:
        report = BrowserGeneralReportInd().deserialize(ind_byte_stream)

        header_part = _get_header_part(report)
        payload_static_part = _get_payload_static_part(report)

        size = int(len(ind_byte_stream[offset:]) / ctypes.sizeof(u32))
        data_array = u32 * size
        # this will have to be removed once response messages are handled as VariableSizeMessages
        if not report.payload_is_little_endian:
            payload_dynamic_part = data_array.from_buffer_copy(change_endianness(ind_byte_stream[offset:]))
        else:
            payload_dynamic_part = data_array.from_buffer_copy(ind_byte_stream[offset:])
        #

        data_string = ''

        for i, item in enumerate(payload_dynamic_part):
            entry = header_part + ',' + payload_static_part

            value = item

            if (item >> data_shift_n) == data_marker:
                value = item & data_mask
                if i != 0:
                    entry += data_string + line_term
                    processed_data.append(entry)
                    data_string = ''

            data_string += ',' + str(value)

        last_entry = header_part + ',' + payload_static_part + data_string + line_term
        processed_data.append(last_entry)

    return processed_data


def _get_header_part(report):
    # type: (BrowserGeneralReportInd) -> str
    fields = (
        report.header.id,
        report.header.pad,
        report.header.receiver.board,
        report.header.receiver.cpu,
        report.header.receiver.task,
        report.header.sender.board,
        report.header.sender.cpu,
        report.header.sender.task,
        report.header.length,
        report.header.flags.system,
        report.header.flags.user
    )
    header_part = ','.join(['{:d}'.format(f) for f in fields])
    return header_part


def _get_payload_static_part(report):
    # type: (BrowserGeneralReportInd) -> str
    fields = (
        report.timeStamp,
        report.contextId,
        report.procedureId,
        report.itemCount,
        report.itemSize
    )
    payload_static_part = ','.join(['{:d}'.format(f) for f in fields])
    return payload_static_part
